ST.xhtml:p:
RtrigClawEnable(CLK := ClampEnable);
RtrigClawOff(CLK := LossenEnable);


IF RtrigClawEnable.Q THEN(*夹紧操作：先上下夹紧，延时时间后左右夹紧*)
    nClawChangeState:=10;
    nTonClawKeep(IN :=FALSE);
    ClawClampTon(IN :=FALSE);
    ClampDone :=FALSE;
    LossenDone := FALSE;
    bClawClampCMDFlag := TRUE;
    bClawLossenCMDFlag := FALSE;
    WaitClampDoneOutTimeAlarm := FALSE;
    WaitLossenDoneOutTimeAlarm := FALSE;
    ClawClampDoneWait(IN :=FALSE);
END_IF;
IF RtrigClawOff.Q THEN
    nClawChangeState:=50;
    nTonClawKeep(IN :=FALSE);
    ClampDone :=FALSE;
    LossenDone := FALSE;
    bClawClampCMDFlag := FALSE;
    bClawLossenCMDFlag := TRUE;
    WaitClampDoneOutTimeAlarm := FALSE;
    WaitLossenDoneOutTimeAlarm := FALSE;
    ClawClampDoneWait(IN :=FALSE);
END_IF;


  CASE nClawChangeState OF
    0:
      nClawChangeState:=0;
    10:
      IF KeepPressure THEN
        ClawKeepPressureDone :=TRUE;
        nClawKeepPressureState := 10; 
      ELSE
        ClawKeepPressureDone :=FALSE; 
      END_IF;
      nClawChangeState:=20; 
    20:
      IF UseClampPlaceSignal THEN
        IF ClampInPlaceSignal THEN  
          nClawChangeState:=150;
          ClawClampDoneWait(IN :=FALSE);
          WaitClampDoneOutTimeAlarm := FALSE;
        END_IF;
         ClawClampDoneWait(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(ChuckDoneWaitTime)));
         IF ClawClampDoneWait.Q THEN
          ClawClampDoneWait(IN := FALSE);
          WaitClampDoneOutTimeAlarm := TRUE;
         END_IF;
      ELSE
        ClawClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(ClampInplaceDelay)));
        IF ClawClampTon.Q THEN
          nClawChangeState:=150;
          ClawClampTon(IN :=FALSE);
        END_IF;
      END_IF;
    50:

      IF KeepPressure THEN
        ClawKeepPressureDone :=TRUE;
        nClawKeepPressureState := 10;
      ELSE
        ClawKeepPressureDone :=FALSE;   
      END_IF; 
      nClawChangeState:=60; 
    60:
      IF UseLossenPlaceSignal  THEN
        IF LossenInPlaceSignal THEN
          nClawChangeState := 150;
          ClawClampDoneWait(IN := FALSE);
          WaitLossenDoneOutTimeAlarm := FALSE;
        END_IF;
         ClawClampDoneWait(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(ChuckDoneWaitTime)));
         IF ClawClampDoneWait.Q THEN
          ClawClampDoneWait(IN := FALSE);
          WaitLossenDoneOutTimeAlarm := TRUE;
         END_IF;
      ELSE  
        ClawClampTon(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(LossenInplaceDelay)));
        IF ClawClampTon.Q THEN
          nClawChangeState := 150;
          ClawClampTon(IN :=FALSE);
        END_IF;
      END_IF;  
    150:  
      IF NOT ClawKeepPressureDone THEN
        IF bClawClampCMDFlag THEN
           ClampDone :=TRUE;
        END_IF;
        IF bClawLossenCMDFlag THEN
			LossenDone := TRUE;
        END_IF;
        nClawChangeState:=0;
      END_IF;    
  END_CASE;  

CASE nClawKeepPressureState OF
  0:
  ;
  10:
    nTonClawKeep(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(KeepPressureTime)));
    ClawKeepPressureDone:= TRUE;
    IF nTonClawKeep.Q THEN
      nTonClawKeep(IN :=FALSE);
      ClawKeepPressureDone := FALSE;
      nClawKeepPressureState:=0;
    END_IF;
END_CASE;
